# AAOS - Emergency Care and Transportation of the Sick and Injured (Jones & Bartlett Learning).
# Chapter list based on the section outline supplied by the site owner, numbered to match library catalog records
# for the 12th edition (e.g., Orthopaedic Injuries = 32, Terrorism Response = 41). Summaries are written for this site.

def ch(n, title, text, keys):
    return (n, title, [text], keys)

C = [
    ch(1, "EMS Systems", "EMS is a coordinated system from dispatch to hospital. Provider levels are EMR, EMT, AEMT, and paramedic. Medical direction can be online or offline (protocols). Quality improvement and continuing education keep care up to standard.", ["Provider levels", "Medical direction", "Quality improvement", "EMT roles"]),
    ch(2, "Workforce Safety and Wellness", "Scene safety comes first. Standard precautions and PPE protect against infection; immunizations and post-exposure plans are required. Stress management, nutrition, sleep, and mental health support prevent burnout.", ["Scene safety", "Standard precautions", "Stress management", "Exposure plans"]),
    ch(3, "Medical, Legal, and Ethical Issues", "Key concepts: scope of practice, consent (expressed, implied, involuntary), refusal of care, abandonment, negligence, confidentiality (HIPAA), advance directives, and mandatory reporting.", ["Consent types", "Refusal of care", "Negligence", "HIPAA"]),
    ch(4, "Communications and Documentation", "EMTs communicate by radio with dispatch and hospitals and give clear handoff reports. The patient care report is a legal record; document objectively, including refusals.", ["Radio reports", "Handoff", "Patient care report", "Document refusals"]),
    ch(5, "Medical Terminology", "Medical terms use prefixes, roots, and suffixes. EMTs use standard anatomical terms, positions (supine, prone, Fowler's, recovery), and approved abbreviations.", ["Word parts", "Positions", "Directional terms", "Abbreviations"]),
    ch(6, "The Human Body", "EMTs need knowledge of body systems: respiratory, cardiovascular, nervous, musculoskeletal, and others, plus anatomical landmarks used in assessment.", ["Body systems", "Anatomical landmarks", "Cardiovascular basics", "Respiratory basics"]),
    ch(7, "Pathophysiology", "Pathophysiology explains how disease disrupts normal function. Cells need oxygen and glucose; inadequate perfusion causes shock. The body compensates by increasing heart and breathing rates.", ["Perfusion", "Cellular metabolism", "Compensation", "Shock basics"]),
    ch(8, "Life Span Development", "Vital signs and behaviors change with age: infants have faster rates, toddlers fear separation, adolescents value privacy, and older adults have decreased reserves and atypical presentations.", ["Age-based vital signs", "Developmental stages", "Adolescent privacy", "Older adult changes"]),
    ch(9, "Lifting and Moving Patients", "Use body mechanics: lift with the legs, keep the load close, avoid twisting. Moves are emergency, urgent, or non-urgent. Equipment includes stretchers, stair chairs, and scoop stretchers.", ["Body mechanics", "Emergency vs. non-urgent moves", "Power lift", "Equipment"]),
    ch(10, "Patient Assessment", "Assessment includes scene size-up, primary assessment (life threats: XABC), history taking (SAMPLE, OPQRST), secondary assessment (DCAP-BTLS), monitoring devices, and reassessment (every 5 minutes unstable, 15 stable).", ["Scene size-up", "Primary assessment", "SAMPLE and OPQRST", "Reassessment"]),
    ch(11, "Airway Management", "Open the airway with head-tilt chin-lift or jaw thrust. Use suction (adult ≤15 seconds), OPAs (no gag reflex), and NPAs. Ventilate with a BVM; give oxygen by nasal cannula or nonrebreather; CPAP helps respiratory distress.", ["Head-tilt chin-lift vs. jaw thrust", "OPA vs. NPA", "BVM ventilation", "Oxygen devices"]),
    ch(12, "Principles of Pharmacology", "EMTs may give or assist with oxygen, oral glucose, aspirin, activated charcoal, epinephrine auto-injectors, nitroglycerin, inhalers, and naloxone, following the rights of medication administration.", ["Medication rights", "EMT medications", "Indications and contraindications", "Routes"]),
    ch(13, "Shock", "Shock is inadequate tissue perfusion. Types: hypovolemic, cardiogenic, distributive (septic, anaphylactic, neurogenic), and obstructive. Early signs are anxiety and tachycardia; hypotension is late. Treat by controlling bleeding, keeping warm, and rapid transport.", ["Types of shock", "Early vs. late signs", "Keep warm", "Rapid transport"]),
    ch(14, "BLS Resuscitation", "High-quality CPR: 100–120 compressions/min, at least 2 inches deep in adults, full recoil, minimal interruptions, and early AED use. Know adult, child, and infant differences and airway obstruction management.", ["CPR rate and depth", "Early AED", "Child and infant CPR", "Choking"]),
    ch(15, "Medical Overview", "Medical patients are assessed with focus on the history (nature of illness). Infectious disease precautions and recognizing time-sensitive conditions are emphasized.", ["Nature of illness", "History focus", "Infection control", "Time-sensitive conditions"]),
    ch(16, "Respiratory Emergencies", "Conditions include asthma, COPD, pneumonia, pulmonary edema, pulmonary embolism, and pneumothorax. Signs of distress: tripod position, accessory muscle use, cyanosis. Assist with inhalers and use CPAP when indicated.", ["Asthma and COPD", "Signs of distress", "Assist with inhalers", "CPAP"]),
    ch(17, "Cardiovascular Emergencies", "Acute coronary syndrome, heart failure, and hypertensive emergencies are common. Give aspirin and assist with nitroglycerin per protocol (not if systolic BP is low or after erectile dysfunction drugs).", ["Acute coronary syndrome", "Aspirin", "Nitro contraindications", "Heart failure"]),
    ch(18, "Neurologic Emergencies", "Stroke (use a stroke scale; time of onset matters), seizures, syncope, and altered mental status are covered. Protect seizing patients from injury.", ["Stroke scales", "Last known well", "Seizures", "Altered mental status"]),
    ch(19, "Gastrointestinal and Urologic Emergencies", "Abdominal pain may be visceral, parietal, or referred; causes include appendicitis, bleeding, and aneurysm. Kidney stones and dialysis complications are urologic emergencies.", ["Types of abdominal pain", "GI bleeding", "AAA", "Dialysis issues"]),
    ch(20, "Endocrine and Hematologic Emergencies", "Hypoglycemia (rapid onset; give oral glucose if able to swallow) and hyperglycemia/DKA (gradual, fruity breath). Hematologic emergencies include sickle cell crisis and clotting disorders.", ["Hypoglycemia", "DKA", "Oral glucose", "Sickle cell crisis"]),
    ch(21, "Immunologic Emergencies", "Allergic reactions range from mild to anaphylaxis (airway swelling, wheezing, hypotension). Give epinephrine by auto-injector and transport rapidly.", ["Anaphylaxis", "Epinephrine auto-injector", "Airway swelling", "Rapid transport"]),
    ch(22, "Toxicology", "Poisons enter by ingestion, inhalation, injection, or absorption. Contact poison control and medical direction. Opioid overdose causes respiratory depression and pinpoint pupils; give naloxone and ventilate.", ["Routes of poisoning", "Poison control", "Opioid overdose", "Naloxone"]),
    ch(23, "Psychiatric Emergencies", "Behavioral emergencies require scene safety, calm communication, and ruling out medical causes. Assess suicide risk. Restraint follows protocol and must avoid positional asphyxia.", ["Scene safety", "Medical causes", "Suicide risk", "Safe restraint"]),
    ch(24, "Gynecologic Emergencies", "Gynecologic emergencies include vaginal bleeding, pelvic inflammatory disease, ectopic pregnancy, and sexual assault. Provide privacy, emotional support, and preserve evidence in assault cases.", ["Vaginal bleeding", "Ectopic pregnancy", "Sexual assault care", "Preserve evidence"]),
    ch(25, "Trauma Overview", "Mechanism of injury (blunt vs. penetrating, falls, vehicle crashes) predicts injuries. Field triage guidelines direct seriously injured patients to trauma centers. Keep scene time short.", ["Mechanism of injury", "Blunt vs. penetrating", "Trauma centers", "Short scene time"]),
    ch(26, "Bleeding", "Control external bleeding with direct pressure, then a tourniquet or wound packing. Recognize internal bleeding by signs of shock. Arterial bleeding is bright red and spurting.", ["Direct pressure", "Tourniquets", "Wound packing", "Internal bleeding signs"]),
    ch(27, "Soft-Tissue Injuries", "Closed injuries (contusions, hematomas) and open injuries (abrasions, lacerations, avulsions, punctures). Stabilize impaled objects; cover open chest wounds with occlusive dressings. Burns are classified by depth and the rule of nines.", ["Open vs. closed", "Impaled objects", "Occlusive dressings", "Burns and rule of nines"]),
    ch(28, "Face and Neck Injuries", "Face and neck injuries threaten the airway. Open neck wounds need occlusive dressings to prevent air embolism. Preserve avulsed teeth and protect eye injuries.", ["Airway threats", "Neck wound occlusive dressing", "Eye injuries", "Avulsed teeth"]),
    ch(29, "Head and Spine Injuries", "Head injuries include concussion and brain bleeding; Cushing's triad signals rising pressure. Use spinal motion restriction for suspected spine injury and monitor GCS.", ["Concussion", "Cushing's triad", "Spinal motion restriction", "GCS"]),
    ch(30, "Chest Injuries", "Chest injuries include rib fractures, flail chest, pneumothorax, tension pneumothorax, hemothorax, and cardiac tamponade. Support breathing and transport rapidly.", ["Flail chest", "Tension pneumothorax", "Hemothorax", "Cardiac tamponade"]),
    ch(31, "Abdominal and Genitourinary Injuries", "Abdominal injuries may cause hidden bleeding; eviscerations are covered with moist sterile dressings (don't push organs back). Genitourinary injuries need privacy and bleeding control.", ["Internal bleeding", "Evisceration care", "Genitourinary injuries", "Shock"]),
    ch(32, "Orthopaedic Injuries", "Fractures, dislocations, sprains, and strains. Check pulse, motor, and sensation before and after splinting; immobilize joints above and below. Traction splints are for midshaft femur fractures.", ["Fractures and dislocations", "PMS checks", "Splinting rules", "Traction splint"]),
    ch(33, "Environmental Emergencies", "Heat emergencies (heat exhaustion, heat stroke), cold emergencies (hypothermia, frostbite), drowning, bites and stings, diving and altitude injuries, and lightning strikes.", ["Heat stroke", "Hypothermia", "Drowning", "Bites and stings"]),
    ch(34, "Obstetrics and Neonatal Care", "Labor has three stages. Assist delivery, check for nuchal cord, dry and warm the newborn, and assess APGAR. Complications include breech, prolapsed cord, eclampsia, and postpartum hemorrhage.", ["Stages of labor", "Newborn care", "APGAR", "Delivery complications"]),
    ch(35, "Pediatric Emergencies", "Children differ in anatomy and vital signs. Use the Pediatric Assessment Triangle (appearance, work of breathing, circulation). Respiratory problems are the leading cause of pediatric cardiac arrest. Watch for signs of abuse.", ["Pediatric Assessment Triangle", "Respiratory causes of arrest", "Age-based vitals", "Child abuse signs"]),
    ch(36, "Geriatric Emergencies", "Older adults have decreased reserves, atypical presentations (silent MI, confusion with infection), polypharmacy, and fall risk. Watch for elder abuse.", ["Atypical presentations", "Polypharmacy", "Falls", "Elder abuse"]),
    ch(37, "Patients With Special Challenges", "Patients may have disabilities or depend on technology (home ventilators, tracheostomies, feeding tubes, VADs). Caregivers are valuable resources.", ["Home medical devices", "Caregivers as resources", "Communication adaptations", "Respect and dignity"]),
    ch(38, "Transport Operations", "Phases of an ambulance call include preparation, dispatch, en route, arrival, transfer, and post-run. Drive with due regard; clean and restock after calls. Air medical landing zones must be secured.", ["Phases of a call", "Due regard", "Cleaning and restocking", "Landing zones"]),
    ch(39, "Vehicle Extrication and Special Rescue", "Extrication steps: size-up, stabilize the vehicle, gain access, disentangle, and remove the patient. Special rescues include water, confined space, and trench rescues requiring specialized teams.", ["Stabilize the vehicle", "Gain access", "Special rescue teams", "Scene safety"]),
    ch(40, "Incident Management", "The Incident Command System and NIMS organize responses. Multiple-casualty incidents use triage (START, SALT). Hazmat scenes have hot, warm, and cold zones.", ["ICS and NIMS", "Triage systems", "Hazmat zones", "Mass casualty"]),
    ch(41, "Terrorism Response and Disaster Management", "Terrorism may involve CBRNE weapons. Recognize indicators, beware of secondary devices, protect yourself with time, distance, and shielding, and follow incident command. Nerve agents cause SLUDGEM signs.", ["CBRNE", "Secondary devices", "Time, distance, shielding", "Nerve agents"]),
]

